"""Explicit Python reconstruction of the fixed Fusion Q44 circuit.

This is a GATE_LEVEL_PYTHON construction, not a recovered arithmetic generator.
The first 1649 operations use recovered arithmetic. Remaining explicit calls
emit KMX instructions; integer operands identify physical
wires/measurement slots, and rotation literals are exact decimal half-turns.
No original submission, text tape, binary, archive or external data is read.
Condition stacks and per-instruction conditions are preserved independently.
The prefix matches INV-66; later region names describe location, not proof of
recovered arithmetic. Syed Asad Ali lineage: see NOTICE.txt.
"""
import kickmix as km
from arithmetic_prefix import build_prefix


class Emitter:
    """Serialize explicit gate calls without float conversion or rescheduling."""

    def __init__(self):
        self.lines = [f'APPEND_TO_REGISTER q{i} r0' for i in range(22)]
        self.lines.append('REGISTER r0 "x"')

    def gate(self, opcode, operands, when):
        line = opcode + ((' ' + ' '.join(operands)) if operands else '')
        if when is not None:
            line += f' if b{when}'
        self.lines.append(line)

    def x(self, a0,when=None):
        self.gate('X', [f'q{a0}'], when)

    def cx(self, a0,a1,when=None):
        self.gate('CX', [f'q{a0}', f'q{a1}'], when)

    def ccx(self, a0,a1,a2,when=None):
        self.gate('CCX', [f'q{a0}', f'q{a1}', f'q{a2}'], when)

    def cz(self, a0,a1,when=None):
        self.gate('CZ', [f'q{a0}', f'q{a1}'], when)

    def z(self, a0,when=None):
        self.gate('Z', [f'q{a0}'], when)

    def hmr(self, a0,a1,when=None):
        self.gate('HMR', [f'q{a0}', f'b{a1}'], when)

    def z_pow(self, a0,a1,when=None):
        self.gate('Z_POW', [f'q{a0}', a1], when)

    def cswap(self, a0,a1,a2,when=None):
        self.gate('CSWAP', [f'q{a0}', f'q{a1}', f'q{a2}'], when)

    def ccz(self, a0,a1,a2,when=None):
        self.gate('CCZ', [f'q{a0}', f'q{a1}', f'q{a2}'], when)

    def swap(self, a0,a1,when=None):
        self.gate('SWAP', [f'q{a0}', f'q{a1}'], when)

    def bit_invert(self, a0,when=None):
        self.gate('BIT_INVERT', [f'b{a0}'], when)

    def bit_store0(self, a0,when=None):
        self.gate('BIT_STORE0', [f'b{a0}'], when)

    def neg(self, when=None):
        self.gate('NEG', [], when)

    def push_condition(self, when=None):
        self.gate('PUSH_CONDITION', [], when)

    def pop_condition(self, when=None):
        self.gate('POP_CONDITION', [], when)









